TLM.f("Tempora/Quad5-2",{"officium":"Feria Tertia infra Hebdomadam Passionis","rule":["no Gloria","Suffragium=Ecclesiæ,Papa;;","Prefatio=Quad5","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"fallback":"Tempora/Quad5-0","sections":{"Introitus":[{"k":"ref","la":"Ps 26:14"},{"k":"text","la":"Exspécta Dóminum, viríliter age: et confortétur cor tuum, et sústine Dóminum."},{"k":"ref","la":"Ps 26:1"},{"k":"text","la":"Dóminus illuminátio mea et salus mea: quem timebo?"},{"k":"text","la":"Exspécta Dóminum, viríliter age: et confortétur cor tuum, et sústine Dóminum."}],"Oratio":[{"k":"text","la":"Nostra tibi, Dómine, quǽsumus, sint accépta jejúnia: quæ nos et expiándo grátia tua dignos effíciant; et ad remédia perdúcant ætérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Daniélis Prophétæ"},{"k":"ref","la":"Dan 14:27, 28-42"},{"k":"text","la":"In diébus illis: Congregáti sunt Babylónii ad regem, et dixérunt ei: Trade nobis Daniélem, qui Bel destrúxit et dracónem interfécit, alióquin interficiémus te, et domum tuam. Vidit ergo rex, quod irrúerent in eum veheménter: et necessitáte compúlsus trádidit eis Daniélem. Qui misérunt eum in lacum leónum, et erat ibi diébus sex. Porro in lacu erant leónes septem, et dabántur eis duo córpora cotídie et duæ oves: et tunc non data sunt eis, ut devorárent Daniélem. Erat autem Hábacuc prophéta in Judǽa, et ipse cóxerat pulméntum, et intríverat panes in alvéolo: et ibat in campum, ut ferret messóribus. Dixítque Angelus Dómini ad Hábacuc: Fer prándium, quod habes, in Babylónem Daniéli, qui est in lacu leónum. Et dixit Hábacuc: Dómine, Babylónem non vidi, et lacum néscio. Et apprehéndit eum Angelus Dómini in vértice ejus, et portávit eum capíllo cápitis sui, posuítque eum in Babylóne supra lacum in ímpetu spíritus sui. Et clamávit Hábacuc, dicens: Dániel, serve Dei, tolle prándium, quod misit tibi Deus. Et ait Dániel: Recordátus es mei, Deus, et non dereliquísti diligéntes te. Surgénsque Daniel comédit. Porro Angelus Dómini restítuit Hábacuc conféstim in loco suo. Venit ergo rex die séptimo, ut lugéret Daniélem: et venit ad lacum et introspéxit, et ecce Dániel sedens in médio leónum. Et exclamávit voce magna rex, dicens: Magnus es, Dómine, Deus Daniélis. Et extráxit eum de lacu leónum. Porro illos, qui perditiónis ejus causa fúerant, intromísit in lacum, et devoráti sunt in moménto coram eo. Tunc rex ait: Páveant omnes habitántes in univérsa terra Deum Daniélis: quia ipse est salvátor, fáciens signa et mirabília in terra: qui liberávit Daniélem de lacu leónum."}],"Graduale":[{"k":"ref","la":"Ps 42:1, 3"},{"k":"text","la":"Discérne causam meam, Dómine: ab hómine iníquo et dolóso éripe me."},{"k":"text","la":"Emítte lucem tuam et veritátem tuam: ipsa me deduxérunt, et adduxérunt in montem sanctum tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 7:1-13"},{"k":"text","la":"In illo témpore: Ambulábat Jesus in Galilǽam, non enim volébat in Judǽam ambuláre, quia quærébant eum Judǽi interfícere. Erat autem in próximo dies festus Judæórum, Scenopégia. Dixérunt autem ad eum fratres ejus: Transi hinc, et vade in Judǽam, ut et discípuli tui vídeant ópera tua, quæ facis. Nemo quippe in occúlto quid facit, et quærit ipse in palam esse: si hæc facis, manifésta teipsum mundo. Neque enim fratres ejus credébant in eum. Dixit ergo eis Jesus: Tempus meum nondum advénit: tempus autem vestrum semper est parátum. Non potest mundus odísse vos: me autem odit: quia ego testimónium perhíbeo de illo, quod ópera ejus mala sunt. Vos ascéndite ad diem festum hunc, ego autem non ascéndo ad diem festum istum: quia meum tempus nondum implétum est. Hæc cum dixísset, ipse mansit in Galilǽa. Ut autem ascendérunt fratres ejus, tunc et ipse ascéndit ad diem festum non maniféste, sed quasi in occúlto. Judǽi ergo quærébant eum in die festo, et dicébant: Ubi est ille? Et murmur multum erat in turba de eo. Quidam enim dicébant: Quia bonus est. Alii autem dicébant: Non, sed sedúcit turbas. Nemo tamen palam loquebátur de illo, propter metum Judæórum."}],"Offertorium":[{"k":"ref","la":"Ps 9:11-12, 13"},{"k":"text","la":"Sperent in te omnes, qui novérunt nomen tuum, Dómine: quóniam non derelínquis quæréntes te: psállite Dómino, qui hábitat in Sion: quóniam non est oblítus oratiónes páuperum."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, deférimus immolándas: quæ temporálem consolatiónem signíficent; ut promíssa non desperémus ætérna."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 24:22"},{"k":"text","la":"Rédime me, Deus Israël, ex ómnibus angústiis meis."}],"Postcommunio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, quæ divína sunt, júgiter exsequéntes, donis mereámur cœléstibus propinquáre."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Da nobis, quǽsumus, Dómine: perseverántem in tua voluntáte famulátum; ut in diébus nostris, et mérito et número, pópulus tibi sérviens augeátur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c24a8d1ca6d7b812":{"t":"Ps 26, 14, Ps 26, 1\n(Ps 26, 14) Čekaj Gospodina, budi hrabar, neka bude jako srce tvoje, i očekuj Gospodina. (Ps 26, 1) Gospodin je svjetlo i spas, koga da se bojim? (Ps 26, 14) Exspécta Dóminum, viríliter age: et confortétur cor tuum, et sústine Dóminum. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]"},"802c6a5a093a908e":{"t":"<i>Pomolimo se</i>.\nNeka ti budu, molimo, Gospodine, prijatni naši postovi, da nas svojim djelovanjem učine dostojnima tvoje milosti i dovedu k izvorima vječnog spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"680cc4906a770dc2":{"t":"Dn 14, 27 i 28-42\nČitanje Danijela proroka. U one dane skupe se Babilonci kod kralja i rekoše: Predaj nam Danijela, koji je satro Bala i pogubio zmaja, jer ćemo inače ubiti tebe i tvoj dom. Kralj je uvidio da su ga teško pritisnuli i primoran preda im Danijela. Ovi ga bace u lavlju jamu i za šest dana nisu ga ni vidjeli. A bilo je u jami sedam lavova kojima su bacali svaki dan dvije strvine i dvije ovce. Ali šest dana im nisu bacili ništa, da što prije prožderu Danijela. U Judeji bio je prorok Habakuk. On je skuhao jelo i išao na polje da ponese žeteocima. Gospodnji anđeo reče Habakuku: Objed što imaš odnesi u Babilon k Danijelu, koji je u lavljoj jami. Habakuk odgovori: »ospodine, nisam nikada vidio Babilona i ne znam gdje je jama. Gospodnji anđeo uhvati ga tada za kosu na vrh glave i jakošću svoga duha prenese ga za čas i postavi u Babilonu nad jamu. I Habakuk poviče: Božji slugo Danijele, uzmi objed što ti Bog šalje. Danijel nato reče: Spomenuo si se, Bože, mene i ne zapuštaš nikoga koji te ljubi! Danijel pojede, a Gospodnji anđeo odmah prenese Habakuka na njegovo mjesto. Sedmi dan dođe kralj da plače za Danijelom. I stade nad jamu i pogleda i vidi Danijela gdje sjedi pa poviče: Velik si Gospodine Bože Danijelov! I izvadi Danijela iz lavlje jame, a one koji su tražili njegovu propast baci u jamu, i za čas su ih na njegov pogled proždrli lavovi. Tada kralj reče: Neka se svi stanovnici zemlje boje Danijelova Boga, jer je on Spasitelj, koji čini znakove i čudesa na zemlji i izbavi Danijela iz lavlje jame!"},"c82271a653c2956a":{"t":"Ps 42, 1 i 3\nSudi mi, Bože, i vodi moju parnicu protiv bezbožna svijeta. Oslobodi me od zlobnog nepravednog čovjeka. Pošalji svoje svjetlo i svoju istinu, da me vode na tvoju svetu goru."},"e9701c28944faa65":{"t":"Iv 7, 32-39\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme obilazio je Isus Galileju, a po Judeji nije htio ići, jer su Židovi tražili da ga ubiju. Bio je skoro židovski blagdan Sjenica, i braća mu kažu: Pođi odavde, idi u Judeju, da i tvoji učenici vide tvoja djela što ih činiš, jer nitko ne djeluje potajno, nego traži da ga upoznaju i drugi. Ako već činiš velika djela, pokaži se svijetu! Ni njegova najbliža rodbina nije vjerovala u njega. A Isus im reče: Još nije došlo moje vrijeme, a vaše vrijeme je uvijek pripravno. Svijet ne može mrziti vas, a mene mrzi, jer tvrdim da su njegova djela zla. Pođite vi na blagdan, a ja ne idem, jer još nije došlo moje vrijeme. Tako on ostane u Galileji. A kad su rođaci pošli na blagdan, pođe i on ne javno, nego potajno. Židovi su ga tražili za vrijeme blagdana i pitali: Pa gdje je on? I u narodu se mnogo govorilo o njemu. Jedni su tvrdili da je dobar, drugi da nije, nego da zavodi narod. Ali nitko nije javno govorio o njemu od straha pred Židovima."},"70f17f809da66315":{"t":"Ps 9, 11-12 i 13\nNek se ufaju u tebe svi koji poznaju ime tvoje, Gospodine, jer ne ostavljaš one koji te traže. Pjevajte Gospodinu na Sionu, jer nije zaboravio vapaj siromaha."},"2f09b006edf20d4a":{"t":"Prinosimo ti, Gospodine, darove za žrtvovanje, što označuju vremenitu utjehu, da se sigurnije uzdamo u vječna obećanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:"},"ae5b5e5b7d61239a":{"t":"Ps 24, 22\nIzbavi me, Bože Izraelov, od svih nevolja mojih."},"e83332f74a313633":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da neprekidno obavljajući ono što je božansko zavrijedimo približiti se nebeskim darovima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7a333e96aed58e82":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nDaj nam, molimo, Gospodine, ustrajnost u tebi ugodnoj službi da se u našim danima umnoži zaslugama i brojem narod koji tebi služi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
